function onlyDigits(v) { return String(v || '').replace(/\D/g, ''); }
function normalizePhone(raw) {
  let p = onlyDigits(raw);
  if (p.startsWith('55') && p.length >= 12) return p;
  if (p.length === 10 || p.length === 11) return '55' + p;
  return p;
}

const raw = items[0].json || {};
const body = raw.body || raw;
const data = body.data || body;
const key = data.key || {};
const msg = data.message || body.message || {};
const remote = key.remoteJid || body.remoteJid || body.from || body.phone || body.sender || '';
const pushName = data.pushName || body.pushName || body.name || '';
const text = msg.conversation || msg?.extendedTextMessage?.text || msg?.imageMessage?.caption || msg?.documentMessage?.caption || body.text || body.messageText || '';
const phone = normalizePhone(remote);
const hasAttachment = Boolean(msg.imageMessage || msg.documentMessage || msg.audioMessage || msg.videoMessage || body.attachment);

return [{
  json: {
    source: 'inbound_whatsapp',
    tenant_id: process.env.DEFAULT_TENANT_ID || '00000000-0000-0000-0000-000000000000',
    channel: 'whatsapp',
    direction: 'inbound',
    phone,
    whatsapp_jid: remote,
    name: pushName,
    text: String(text || '').trim(),
    has_attachment: hasAttachment,
    received_at: new Date().toISOString(),
    provider_payload: body
  }
}];

const response = items[0]?.json;
const rows = Array.isArray(response) ? response : (Array.isArray(response?.data) ? response.data : []);
return rows.map((row) => {
  const debtor = row.debtor || row.cobranca_debtors || row.debtor_id || {};
  return {
    json: {
      source: 'scheduled_collection',
      tenant_id: row.tenant_id || process.env.DEFAULT_TENANT_ID,
      channel: debtor.preferred_channel || 'whatsapp',
      direction: 'outbound',
      phone: debtor.phone,
      email: debtor.email,
      name: debtor.name,
      debtor,
      debt: row,
      text: '',
      received_at: new Date().toISOString()
    }
  };
});

function brl(value) {
  const n = Number(value || 0);
  return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}
function daysBetween(a, b) {
  const A = new Date(a); const B = new Date(b);
  return Math.floor((B - A) / 86400000);
}
function greeting() {
  const hour = Number(new Intl.DateTimeFormat('pt-BR', { hour: '2-digit', hour12: false, timeZone: process.env.DEFAULT_TIMEZONE || 'America/Sao_Paulo' }).format(new Date()));
  if (hour < 12) return 'Bom dia';
  if (hour < 18) return 'Boa tarde';
  return 'Boa noite';
}
function currentHour() {
  return Number(new Intl.DateTimeFormat('pt-BR', { hour: '2-digit', hour12: false, timeZone: process.env.DEFAULT_TIMEZONE || 'America/Sao_Paulo' }).format(new Date()));
}
function detectIntent(text, hasAttachment) {
  const t = String(text || '').toLowerCase();
  if (hasAttachment) return 'proof_or_attachment';
  if (/\b(paguei|pagamento feito|comprovante|ja paguei|já paguei|quitado)\b/.test(t)) return 'paid_claim';
  if (/\b(não reconheço|nao reconheco|não é minha|nao e minha|indevida|errado|desconheço|desconheco)\b/.test(t)) return 'dispute';
  if (/\b(negociar|acordo|parcelar|parcela|desconto|proposta)\b/.test(t)) return 'negotiate';
  if (/\b(boleto|pix|segunda via|link|codigo|código)\b/.test(t)) return 'payment_link';
  if (/\b(atendente|humano|pessoa|ligar|me liga)\b/.test(t)) return 'human';
  if (/\b(advogado|procon|processo|reclamação|reclamacao)\b/.test(t)) return 'legal_sensitive';
  if (/\b(parar|não mande|nao mande|remover|bloquear|sair)\b/.test(t)) return 'opt_out';
  return 'general';
}
function stageFromDays(days) {
  if (days < 0) return 'pre_due';
  if (days <= 2) return 'd0_d2';
  if (days <= 6) return 'd3_d6';
  if (days <= 14) return 'd7_d14';
  if (days <= 29) return 'd15_d29';
  return 'd30_plus';
}

const input = $json;
let debtor = input.debtor || {};
let debt = input.debt || {};

// Se veio do lookup REST, alguns retornos chegam como array.
if (!input.debt && Array.isArray($json)) {
  const row = $json[0] || {};
  debtor = row;
  debt = row.debts?.[0] || row.cobranca_debts?.[0] || {};
}

const now = new Date();
const startHour = Number(process.env.COLLECTION_START_HOUR || 8);
const endHour = Number(process.env.COLLECTION_END_HOUR || 20);
const hour = currentHour();
const withinHours = hour >= startHour && hour < endHour;
const daysOverdue = debt.due_date ? daysBetween(debt.due_date, now) : 0;
const stage = debt.stage || stageFromDays(daysOverdue);
const intent = detectIntent(input.text, input.has_attachment);
const name = input.name || debtor.name || 'tudo bem';
const amount = brl(debt.current_amount || debt.original_amount || 0);
const paymentLink = debt.payment_link || debt.boleto_url || '';
const pix = debt.pix_code || '';

const blockingReasons = [];
if (!withinHours) blockingReasons.push('outside_allowed_hours');
if (debtor.opt_out || intent === 'opt_out') blockingReasons.push('opt_out');
if (debtor.dispute_status === 'open' || debt.status === 'disputed' || intent === 'dispute') blockingReasons.push('dispute_open');
if (['paid','cancelled','canceled','uncollectible'].includes(String(debt.status || '').toLowerCase())) blockingReasons.push('debt_not_collectable');
if (['paid_claim','proof_or_attachment','legal_sensitive','human'].includes(intent)) blockingReasons.push('human_review_required');

const canContact = blockingReasons.length === 0;
let shouldWhatsApp = canContact && Boolean(input.phone || debtor.phone);
let shouldEmail = canContact && Boolean(input.email || debtor.email) && ['d3_d6','d7_d14','d15_d29','d30_plus'].includes(stage);
let shouldCall = canContact && Boolean(input.phone || debtor.phone) && ['d7_d14','d15_d29'].includes(stage);
let shouldHuman = !canContact || ['d30_plus'].includes(stage) || debt.human_required || debtor.human_required;

let baseMessage = '';
if (intent === 'payment_link') {
  baseMessage = `${name}, posso te ajudar sim. ${paymentLink ? 'Segue o link atualizado para regularização: ' + paymentLink : 'Vou localizar a segunda via e te enviar com segurança.'}${pix ? '\nPix copia e cola: ' + pix : ''}`;
} else if (intent === 'negotiate') {
  baseMessage = `${name}, claro. Posso verificar uma alternativa para regularização. Você prefere pagar à vista com desconto ou parcelar?`;
} else if (intent === 'dispute') {
  baseMessage = `${name}, entendi. Vou pausar a cobrança automática e encaminhar para conferência humana. Para agilizar, pode me informar qual dado está incorreto?`;
} else if (intent === 'paid_claim' || intent === 'proof_or_attachment') {
  baseMessage = `${name}, obrigado pelo retorno. Vou pausar a cobrança automática e encaminhar o comprovante/informação para validação.`;
} else if (stage === 'pre_due') {
  baseMessage = `${greeting()}, ${name}. Passando para lembrar de um vencimento programado. Posso te enviar o link atualizado para pagamento?`;
} else if (stage === 'd0_d2') {
  baseMessage = `${greeting()}, ${name}. Identificamos uma pendência recente no valor de ${amount}. Quer que eu te envie o link/Pix atualizado para regularizar?`;
} else if (stage === 'd3_d6') {
  baseMessage = `${name}, estou passando de forma rápida para te ajudar com a pendência em aberto. Posso verificar uma opção de pagamento ou negociação para você?`;
} else if (stage === 'd7_d14') {
  baseMessage = `${name}, sua pendência continua em aberto. Posso te ajudar agora com pagamento à vista ou uma proposta de acordo?`;
} else if (stage === 'd15_d29') {
  baseMessage = `${name}, precisamos atualizar a situação do seu contrato. Posso registrar uma previsão de pagamento ou proposta para análise?`;
} else {
  baseMessage = `${name}, seu caso precisa de uma revisão mais cuidadosa. Vou encaminhar para um especialista da assessoria verificar a melhor alternativa de regularização.`;
}

return [{ json: {
  ...input,
  tenant_id: input.tenant_id || debtor.tenant_id || debt.tenant_id || process.env.DEFAULT_TENANT_ID,
  debtor_id: debtor.id || debt.debtor_id || null,
  debt_id: debt.id || null,
  creditor_id: debt.creditor_id || debtor.creditor_id || null,
  debtor,
  debt,
  stage,
  days_overdue: daysOverdue,
  intent,
  name,
  amount,
  payment_link: paymentLink,
  pix_code: pix,
  compliance: {
    canContact,
    withinHours,
    blockingReasons,
    startHour,
    endHour,
    rule: 'CDC_LGPD_SAFE_COLLECTION'
  },
  shouldWhatsApp,
  shouldEmail,
  shouldCall,
  shouldHuman,
  typingSeconds: Math.min(10, Math.max(4, Math.ceil(baseMessage.length / 45))),
  fallback_message: baseMessage,
  emailSubject: `Regularização de pendência${debt.contract_ref ? ' - contrato ' + debt.contract_ref : ''}`,
  emailBody: `Olá, ${name}.\n\nIdentificamos uma pendência vinculada ao seu cadastro${debt.contract_ref ? ' / contrato ' + debt.contract_ref : ''}.\nValor atualizado: ${amount}.\n\n${paymentLink ? 'Link para regularização: ' + paymentLink : 'Caso queira, responda este e-mail para receber a segunda via atualizada.'}\n\nSe você já pagou ou não reconhece esta cobrança, responda esta mensagem para conferirmos com prioridade.\n\nAtenciosamente,\nEquipe de Atendimento`,
  ai_prompt: `Você é um agente de IA de uma assessoria de cobrança no Brasil. Gere uma mensagem curta, humana, cordial e segura para WhatsApp. Regras: não ameaçar, não constranger, não expor, não citar negativação/processo/protesto, não falar com terceiros, não usar tom agressivo, no máximo 3 frases curtas, fazer no máximo 1 pergunta, respeitar LGPD/CDC. Contexto: nome=${name}; etapa=${stage}; intenção=${intent}; valor=${amount}; link=${paymentLink || 'indisponível'}; mensagem_base=${baseMessage}`
}}];

const previous = $('Preparar Prompt IA').item.json;
let aiText = '';
try {
  aiText = $json?.choices?.[0]?.message?.content || $json?.output_text || '';
} catch (e) {}
let finalText = String(aiText || previous.fallback_message || '').trim();

const forbidden = /(ameaç|ameaça|processo judicial imediato|pris[aã]o|vergonha|caloteiro|sujo|expor|família|familia|vizinhos|empregador|negativar hoje|protesto hoje)/i;
const tooLong = finalText.length > 650;
if (!finalText || forbidden.test(finalText) || tooLong) {
  finalText = previous.fallback_message;
}

// Quebra mensagem em blocos curtos sem perder clareza.
finalText = finalText
  .replace(/\s+/g, ' ')
  .replace(/\. /g, '.\n')
  .trim();

return [{ json: { ...previous, final_message: finalText } }];
